import{_ as o,o as r,c as a,a3 as t}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"Purchase Orders — Production Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Purchase Orders — Production Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/purchase-orders"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Purchase Orders — Production Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/purchase-orders"}]]},"headers":[],"relativePath":"deployment/purchase-orders.md","filePath":"deployment/purchase-orders.md","lastUpdated":1787271837000}'),s={name:"deployment/purchase-orders.md"};function n(d,e,c,i,l,p){return r(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="purchase-orders-—-production-guide" tabindex="-1">Purchase Orders — Production Guide <a class="header-anchor" href="#purchase-orders-—-production-guide" aria-label="Permalink to &quot;Purchase Orders — Production Guide&quot;">​</a></h1><h2 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h2><ul><li>Catalog slug: <code>purchase-orders</code></li><li>Category: <code>purchasing</code> (<strong>Purchasing</strong>), <code>category_sort_order = 40</code>, <code>sort_order = 20</code></li><li><strong>Free Marketplace opt-in</strong> module (not auto-installed)</li><li>Catalog flags: <code>is_default_included = false</code>, <code>is_billable = false</code>, price <code>0</code></li><li><strong>Hard dependency on Vendors</strong> — Marketplace blocks installing Purchase Orders on a workspace that doesn&#39;t already have Vendors entitled</li><li>New workspaces receive only <strong>Leads</strong> + <strong>Tasks</strong> by default; enable Vendors, then Purchase Orders, from Marketplace</li><li>Existing workspaces that already have Purchase Orders keep their subscription</li><li>Deactivate via Central module subscription tools to revoke access without dropping data</li></ul><h2 id="bootstrap" tabindex="-1">Bootstrap <a class="header-anchor" href="#bootstrap" aria-label="Permalink to &quot;Bootstrap&quot;">​</a></h2><p>On <strong>new workspace</strong> create (Central tenant create or public register):</p><ol><li><code>installDefaultModules()</code> installs published <code>is_default_included</code> modules (<strong>Leads</strong>, <strong>Tasks</strong> only)</li><li>Operators enable <strong>Vendors</strong> first, then <strong>Purchase Orders</strong>, from Marketplace (free / non-billable install activates immediately)</li><li>Tenant permissions include <code>purchase-orders.*</code> via <code>config/tenant-permissions.php</code> / default role maps</li></ol><p>No stage or status seeder — purchase order status defaults to <code>draft</code> at creation time and advances via the state machine.</p><h2 id="permissions-rollout" tabindex="-1">Permissions rollout <a class="header-anchor" href="#permissions-rollout" aria-label="Permalink to &quot;Permissions rollout&quot;">​</a></h2><p>New Purchase Orders permissions for <strong>existing</strong> workspaces must ship as an additive <strong>data migration</strong> using <code>TenantPermissionSynchronizer::grantMissingDefaultRolePermissions([...])</code>. Do <strong>not</strong> re-seed roles or rely on login/dashboard to repair RBAC.</p><h2 id="tenant-settings" tabindex="-1">Tenant settings <a class="header-anchor" href="#tenant-settings" aria-label="Permalink to &quot;Tenant settings&quot;">​</a></h2><p><code>purchase_orders_number_prefix</code> (default <code>PO-</code>) controls the auto-generated <code>number</code> prefix, same mechanism as <code>estimates_number_prefix</code>. Updatable via <code>PUT /api/tenant/v1/settings</code>.</p><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><ul><li>Platform audit events: <code>purchase_order_created</code>, <code>purchase_order_updated</code>, <code>purchase_order_deleted</code>, <code>purchase_order_assigned</code>, <code>purchase_order_status_changed</code>, <code>purchase_order_note_added</code>, <code>purchase_order_restored</code></li><li>Notifications: assignment (mail + database) via <code>PurchaseOrderAssignedNotification</code></li><li>Tenant mail settings with Central SMTP fallback</li></ul><h2 id="deploy-checklist" tabindex="-1">Deploy checklist <a class="header-anchor" href="#deploy-checklist" aria-label="Permalink to &quot;Deploy checklist&quot;">​</a></h2><ol><li>Migrate purchase order tables (<code>purchase_orders</code>, <code>purchase_order_lines</code>, <code>purchase_order_notes</code>, <code>purchase_order_activities</code>)</li><li>Register the <code>purchase-orders</code> catalog module (migration, not seeder) as free opt-in under the <code>purchasing</code> category, with a <code>module_dependencies</code> row on <code>vendors</code></li><li>Confirm <code>module:purchase-orders</code> + <code>purchase-orders.*</code> permissions on target roles</li><li>Deploy frontend (Purchase Orders nav item under <strong>Purchasing</strong>, after Vendors — list/form/detail)</li><li>Smoke: create a <strong>new</strong> workspace → enable Vendors, then Purchase Orders, from Marketplace → create a vendor → create/edit/assign/note a purchase order → send → mark partially received → mark received → soft delete/restore</li></ol><h2 id="convert-to-expense-soft-milestone-3" tabindex="-1">Convert to expense (soft, Milestone 3) <a class="header-anchor" href="#convert-to-expense-soft-milestone-3" aria-label="Permalink to &quot;Convert to expense (soft, Milestone 3)&quot;">​</a></h2><p>Once the <strong>Expenses</strong> module is also enabled, <code>sent</code>/<code>partially_received</code>/<code>received</code> purchase orders can be converted to a draft Expense via <code>POST /purchase-orders/{id}/convert</code>, gated by the <code>purchase-orders.convert</code> permission and a soft (call-time) entitlement check — not a hard <code>module_dependencies</code> row. See <a href="/deployment/expenses">Expenses — Production Guide</a>.</p><h2 id="phase-4-roadmap-context" tabindex="-1">Phase 4 roadmap context <a class="header-anchor" href="#phase-4-roadmap-context" aria-label="Permalink to &quot;Phase 4 roadmap context&quot;">​</a></h2><p>Purchase Orders is Milestone 2 of <strong>Phase 4 Purchasing</strong>, hard-depending on Vendors (Milestone 1). Expenses (Milestone 3, final) has a soft dependency on Vendors and Purchase Orders and adds the convert-from-purchase-order action described above. Phase 4 Purchasing is now complete. See <a href="/architecture/module-dependencies">module-dependencies.md</a> and <a href="/getting-started/product-roadmap">product-roadmap.md</a>.</p>',19)])])}const m=o(s,[["render",n]]);export{u as __pageData,m as default};
